from collections import defaultdict

class Solution:
    def isEulerian(self, V, adj):
        if not adj:
            return 0

        # Check if all non-zero degree vertices are connected
        def isConnected(u, V, adj):
            visited = [False] * V
            count = 0

            def dfs(u):
                visited[u] = True
                for v in adj[u]:
                    if not visited[v]:
                        dfs(v)

            for i in range(V):
                if len(adj[i]) > 0:
                    dfs(i)
                    break

            for i in range(V):
                if not visited[i] and len(adj[i]) > 0:
                    return False

            return True

        # Count odd degree vertices
        odd = 0
        for i in range(V):
            if len(adj[i]) % 2 != 0:
                odd += 1

        # If count is more than 2, then it is not Eulerian
        if odd > 2:
            return 0

        # If there are 0 odd vertices, then it has a Eulerian circuit
        if odd == 0:
            return 2

        # If there are 2 odd vertices, then it has a Eulerian path
        if odd == 2:
            return 1

        return 0

